INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Umfasst 2001:db8:1::/64 genau ein Subnetz?', 2, '[{"text": "Ja", "correct": true, "because": "/64 definiert ein Subnetz"}, {"text": "Nein", "correct": false, "because": "Standardgröße"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Adressen enthält der Bereich 2001:db8:1::/64?', 3, '[{"text": "2^64", "correct": true, "because": "64 Bits für Interface-ID"}, {"text": "2^48", "correct": false, "because": "Zu klein"}, {"text": "2^128", "correct": false, "because": "Gesamter Adressraum"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Bereich deckt 2001:db8:1::/64 ab?', 4, '[{"text": "2001:db8:1:0:0:0:0:0 bis 2001:db8:1:0:ffff:ffff:ffff:ffff", "correct": true, "because": "64-Bit-Netzwerkanteil"}, {"text": "2001:db8:1:: bis 2001:db8:2::", "correct": false, "because": "Nächstes Subnetz"}, {"text": "2001:db8:: bis 2001:db8:1::", "correct": false, "because": "Falscher Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 2001:db8:1::/64 ist ein Subnetz. b) Es ist global routbar.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Ein Subnetz und 2000::/3 ist routbar"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Adressbereich wie 2001:db8:1::/64?', 5, '[{"text": "Einzelne Hostadressen", "correct": true, "because": "Bereich definiert Subnetz"}, {"text": "Netzwerkpräfix", "correct": false, "because": "Kern des Bereichs"}, {"text": "Subnetzgrenze", "correct": false, "because": "Definiert durch /64"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 2001:db8:1::/64 mehrere Subnetze enthält?', 2, '[{"text": "Nein", "correct": true, "because": "/64 ist ein Subnetz"}, {"text": "Ja", "correct": false, "because": "Nur ein Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Bereich folgt auf 2001:db8:1::/64?', 3, '[{"text": "2001:db8:2::/64", "correct": true, "because": "Nächstes Subnetz"}, {"text": "2001:db8:1:1::/64", "correct": false, "because": "Innerhalb desselben"}, {"text": "2001:db9::/64", "correct": false, "because": "Falsche Schrittweite"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat der Bereich 2001:db8:1::/64?', 5, '[{"text": "2^64 Adressen", "correct": true, "because": "Interface-ID-Bereich"}, {"text": "Global Unicast", "correct": true, "because": "2000::/3"}, {"text": "Link-Local", "correct": false, "because": "FE80::/10"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) 2001:db8:1::/64 ist für Dokumentation. b) Es ist nicht routbar. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "2001:db8::/32 ist für Docs, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für den Bereich 2001:db8:1::/64?', 4, '[{"text": "Netzwerkpräfix", "correct": false, "because": "Definiert Bereich"}, {"text": "Subnetzgrenze", "correct": false, "because": "Durch /64 gegeben"}, {"text": "Einzelne IP-Liste", "correct": true, "because": "Bereich genügt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist 2001:db8:1::/64 ein privater Bereich?', 2, '[{"text": "Nein", "correct": true, "because": "Global Unicast, nicht FC00::/7"}, {"text": "Ja", "correct": false, "because": "Falscher Adresstyp"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Teile definieren 2001:db8:1::/64?', 4, '[{"text": "Netzwerkpräfix", "correct": true, "because": "2001:db8:1:0"}, {"text": "Interface-ID-Bereich", "correct": true, "because": "Letzte 64 Bits"}, {"text": "Multicast-Flag", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass 2001:db8:1::/64 nur für Tests ist. Stimmt das?', 3, '[{"text": "Ja", "correct": true, "because": "2001:db8::/32 für Dokumentation"}, {"text": "Nein", "correct": false, "because": "Technisch routbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Bereich wie 2001:db8:1::/64?', 3, '[{"text": "Subnetzgrenze", "correct": true, "because": "Definiert den Bereich"}, {"text": "Einzeladressen", "correct": false, "because": "Sekundär"}, {"text": "Kürzungsregeln", "correct": false, "because": "Darstellungssache"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 2001:db8:1::/64 hat 2^64 Adressen. b) Es ist für LAN gedacht.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) ist mathematisch, b) ist üblich"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Bereich wie 2001:db8:1::/64?', 5, '[{"text": "Großer Adresspool", "correct": true, "because": "2^64 Adressen"}, {"text": "SLAAC-Unterstützung", "correct": true, "because": "/64 ist kompatibel"}, {"text": "Kleine Subnetze", "correct": false, "because": "Relativ groß"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei 2001:db8:1::/64 unwichtig?', 3, '[{"text": "Netzwerkpräfix", "correct": false, "because": "Definiert Bereich"}, {"text": "Subnetzgröße", "correct": false, "because": "Durch /64 gegeben"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann 2001:db8:1::/64 weiter unterteilt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Bits können geliehen werden"}, {"text": "Nein", "correct": false, "because": "Flexibel nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 2001:db8:1::/64 für öffentliche Netze ist?', 3, '[{"text": "Ja", "correct": true, "because": "2000::/3 ist global"}, {"text": "Nein", "correct": false, "because": "Dokumentation, aber routbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Bereich liegt vor 2001:db8:1::/64?', 4, '[{"text": "2001:db8:0::/64", "correct": true, "because": "Vorheriges Subnetz"}, {"text": "2001:db8:1:0::/64", "correct": false, "because": "Derselbe Bereich"}, {"text": "2001:db7::/64", "correct": false, "because": "Falsche Schrittweite"}]');
